 void cancelImages(){imageEpoch++;posters.getQueue().clear();for(android.os.CancellationSignal signal:imageRequests)signal.cancel();imageRequests.clear();}
 void loadPoster(ImageView view,String path,int token){if(path.isEmpty()||path.equals("null"))return;Bitmap cached=posterCache.get(path);if(cached!=null){view.setImageBitmap(cached);return;}posters.execute(()->{if(!alive||!screenActive||token!=imageEpoch)return;android.os.CancellationSignal signal=new android.os.CancellationSignal();imageRequests.add(signal);Bitmap image=null;try{if(!screenActive||token!=imageEpoch)signal.cancel();image=MovieClient.poster(this,path,signal);}catch(Exception ignored){}finally{imageRequests.remove(signal);}final Bitmap ready=image;handler.post(()->{if(ready==null)return;if(alive&&screenActive&&token==imageEpoch){posterCache.put(path,ready);view.setImageBitmap(ready);}else ready.recycle();});});}
