 void markMenu(JSONObject movie){new LauncherDialogs.Builder(this).setTitle(movie.optString("title")).setItems(new String[]{history.seen(movie.optInt("id"))?"Убрать отметку «Смотрел»":"Отметить «Смотрел»","Подробности"},(d,n)->{if(n==0)mark(movie);else details(movie);}).setNegativeButton("Назад",null).show();}
